def analyze(k):
    i=np.array(G[k+' input']); o=np.array(G[k+' output'])
    print('===',k)
    U=set(np.unique(i))
    for c in sorted(U):
        if c in (0,2) or (c==0): continue
        Ps=list(zip(*np.where(i==c))); Os=list(zip(*np.where(o==c)))
        info=[]
        for (r,j) in Ps:
            best=None
            for dr,dc in ((-1,-1),(-1,1),(1,-1),(1,1)):
                # is any Os cell on this diagonal from (r,j)?
                pts=[p for p in Os if (p[0]-r)*dc==(p[1]-j)*dr and (p[0]-r)//dr== (p[1]-j)//dc and abs(p[0]-r)>=1]
                if pts:
                    d=min(abs(p[0]-r)+abs(p[1]-j) for p in pts)
                    if best is None or d<best[0]: best=(d,(dr,dc),min(pts,key=lambda p:(p[0]-r)+abs(p[1]-j)))
            info.append(((int(r),int(j)),best))
        print(' color',c,'in:',Ps)
        for p,b in info: print('   ',p,b)
