    analyze(k)

def diag_cells(P,c,O):
    # P=(r,j) input dot; O list of output cells of color c
    res={}
    for dr,dc in ((-1,-1),(-1,1),(1,-1),(1,1)):
        pts=[p for p in O if abs(p[0]-P[0])==abs(p[1]-P[1]) and (p[0]-P[0])*dc==(p[1]-P[1])*dr]
        if pts:
            res[(dr,dc)]=(min(pts,key=lambda p:(abs(p[0]-P[0]))),max(pts,key=lambda p:(abs(p[0]-P[0]))) )
    return res
