def solve(k, dir_choices=None, stop_at_2=True, stop_at_other=False, max_steps=8):
    i=np.array(G[k+' input']); o=np.array(G[k+' output'])
    H,W=i.shape
    bs=blocks_of(i)
    Ps=list(zip(*np.where(i!=2)))
