    # start with blocks + dots painted? We'll paint rays one by one from original grid state.
    grid=[[int(v) for v in row] for row in i.tolist()]
    done=set(Ps)
    changed=True
    while changed:
        changed=False
        for p in sorted(done):
            r,c=p
            v=int(i[r,c])
            best=None
            for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                nb=min(abs(r+dr-br)+abs(c+dc-bcc) for bb in bs for br,bcc in bb)
                cand=(nb,dr,dc)
                if best is None or cand[0]<best[0] or (cand[0]==best[0] and (dr,dc)<best[1]):
                    best=cand
            nr,nc=r+best[1]; nb=best[0]; _,_,_ = nb,(r+best[1]),(c+best[2]) if False else None
            rr,cc=nrc,ncc
            steps=0
            while steps<max_steps and 0<=rr<H and 0<=cc<W:
                val=grid[rr][cc]
                if val==0:
                    res[rr][cc]=v; rr+=best[1]; cc+=best[2]; steps+=1
                elif (stop_at_other or val==v) and True: 
                    pass
                else:
                    break
                if val!=0 and not (stop_at_2 and val!=2):
                    break
                if not(stop_at_2 or val==2): break
        if not changed: break
    return np.array(res)

