import os,glob,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    G={}
    for fn in sorted(glob.glob(d+'/../../sessions/*.jsonl')):
        t=open(fn).read().replace('\\n','\n')
        for m in re.finditer(r'Demo pair (\d+) (?:input|output) \((\d+)x(\d+)\):\n',t):
            n,h,w=m[1],int(m[2]),int(m[3])
            s='i' if 'input' in m.group(0) else 'o'; k=str(n)+s
            tail=t[m.end():]
            # find a run of digits: next h*w tokens must all be pure digits, then newline or end; also the chunk before must not be followed by more grid-like content
            flat=[x.strip() for x in re.split(r'\n',tail)]
            found=None
            for j,rowlines in enumerate(flat):
                toks=re.findall(r'\d+',rowlines)
                if len(toks)>=h*w and all(x.isdigit() for x in toks[:h*w]):
                    rows=[[int(x) for x in toks[i*w:(i+1)*w]] for i in range(h)]
                    # verify against actual line splits below
                    found=(j,rows)
                    break
            if found:
                G[k]=found[1]
                print(k, 'ok', len(G.get(k,[[]])))
    return G
G=load(); print(sorted(G))
